def priority(SH: float, EMP: float, AVG: float, CUR: float, RI: float, DIFF: float) -> float:
    """Score one candidate stack for the container being relocated. Lowest score wins."""
    # Urgency of the current container: more urgent (lower ID) has higher priority
    urgency = 1 / (CUR + 1)

    # Free space priority: more free space is better; use exponential urgency-aware scaling
    free_space_weight = 0.3 * (1 / (EMP + 1)) * (1 + urgency**2)

    # Average ID priority: lower average ID is better; use adaptive scaling
    if AVG < CUR:
        avg_id_weight = 0.25 * (AVG / (CUR + 1))
    else:
        avg_id_weight = 0.25 * (AVG / (CUR + 10))

    # Future blocking: minimize the number of containers with smaller IDs (RI), with saturation-sensitive logarithmic penalty
    if SH - EMP > 0:
        future_blocking_weight = 0.2 * (RI / (SH - EMP + 1)) * (1 - (SH - EMP) / 100)
    else:
        future_blocking_weight = 0.2 * (RI / 2) * (1 - (SH - EMP) / 100)

    # Difference weight: prefer stacks with larger DIFF (no smaller IDs); use inverse urgency scaling
    if DIFF < 1e9:
        diff_weight = 0.1 * (DIFF / (1e9 + 1)) * (1 - urgency)
    else:
        diff_weight = 0.1 * (1 - urgency)

    # Stack height: discourage very tall stacks, with urgency-modified penalty
    if SH < 100:
        stack_height_weight = 0.1 * (SH / 100) * (1 + urgency)
    else:
        stack_height_weight = 0.1 * 1

    # Final priority score
    priority = free_space_weight + avg_id_weight + future_blocking_weight + diff_weight + stack_height_weight
    return priority
